css:
.doc-header { margin-bottom: 28px; }
.doc-header__titlewrap { display: flex; align-items: baseline; flex-wrap: wrap; gap: 12px; }
.doc-header .article__title { margin-bottom: 8px; }
.doc-header__meta { display: flex; align-items: center; flex-wrap: wrap; gap: 16px; margin-top: 10px; font-size: 13px; color: var(--pds-text-secondary); }
.doc-header__edited a { color: var(--pds-text-secondary); font-weight: 600; }
.doc-header__edited a:hover { color: var(--pds-link); }
.doc-edit-row { margin: 48px 0 8px; padding-top: 20px; border-top: 1px solid var(--pds-border-subtle); font-size: 13px; color: var(--pds-text-secondary); }
.doc-edit-link { color: var(--pds-text-secondary); font-weight: 600; text-decoration: none; }
.doc-edit-link:hover { color: var(--pds-link); text-decoration: underline; }
html[data-auth="anon"] .doc-edit-row { display: none; }
